"""Migration of the Meridian CRM 4.2 credit-hold sweep."""

from decimal import Decimal, InvalidOperation
from typing import Any


_ZERO = Decimal("0")
_EIGHT_TENTHS = Decimal("0.8")


def _number(value: Any) -> Decimal:
    """Apply legacy NVL/numeric coercion: missing or empty values are zero."""
    if value is None or value == "":
        return _ZERO
    try:
        # str() avoids binary floating-point comparison artifacts for float inputs.
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return _ZERO


def _primary_key(value: Any) -> tuple[int, Any]:
    """Provide deterministic ascending ordering for normally string ACCT_ID keys."""
    if value is None:
        return (0, "")
    if isinstance(value, (int, Decimal)):
        return (1, value)
    return (2, str(value))


def sweep(accounts: list[dict], orders: list[dict]) -> tuple[list[dict], list]:
    """Run the nightly credit-hold sweep without mutating either input collection."""
    new_accounts = [dict(account) for account in accounts]
    audits: list[tuple[str, Any]] = []

    exposure_by_account: dict[Any, Decimal] = {}
    for order in orders:
        if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") != "I":
            continue

        acct_id = order.get("ACCT_ID")
        exposure_by_account[acct_id] = (
            exposure_by_account.get(acct_id, _ZERO) + _number(order.get("TOT_AMT"))
        )

    eligible_indices = [
        index
        for index, account in enumerate(new_accounts)
        if account.get("DEL_FLG") != "Y" and account.get("ACCT_TYP") == "C"
    ]
    eligible_indices.sort(key=lambda index: _primary_key(new_accounts[index].get("ACCT_ID")))

    for index in eligible_indices:
        account = new_accounts[index]
        acct_id = account.get("ACCT_ID")
        exposure = exposure_by_account.get(acct_id, _ZERO)
        credit_limit = _number(account.get("CRED_LIMIT"))

        # These are intentionally separate IF blocks, preserving script evaluation order.
        if exposure > credit_limit and account.get("CRED_HOLD") != "Y":
            account["CRED_HOLD"] = "Y"
            audits.append(("CRED_HOLD_ON", acct_id))

        if exposure <= credit_limit * _EIGHT_TENTHS and account.get("CRED_HOLD") == "Y":
            account["CRED_HOLD"] = "N"
            audits.append(("CRED_HOLD_OFF", acct_id))

    return new_accounts, audits
